import {finaleSources as S} from './integrated-cases-scenes.js';
const credit=(url,label)=>`<a href="${url}" target="_blank" rel="noreferrer">${label}</a>`;
const foot=(...links)=>`<p class="f-credit">${links.join(' · ')}</p>`;
const img=(name,alt,cls='')=>`<img class="${cls}" src="../assets/references/${name}" alt="${alt}">`;
const text=(x,y,value,cls='',anchor='middle')=>`<text x="${x}" y="${y}" text-anchor="${anchor}" class="${cls}">${value}</text>`;
const wire=(d,kind='power',extra='')=>`<path d="${d}" class="f-wire ${kind} ${extra}" marker-end="url(#f-${kind})"/>`;
const defs=`<defs>${['power','heat','information','cool'].map(k=>`<marker id="f-${k}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 1L9 5L0 9Z" class="f-arrow ${k}"/></marker>`).join('')}</defs>`;
const svg=(body,label,view='0 0 1120 420')=>`<svg viewBox="${view}" role="img" aria-label="${label}">${defs}${body}</svg>`;
const box=(x,y,w,h,label,sub='',cls='')=>`<g class="f-machine ${cls}"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="8"/>${text(x+w/2,y+h/2+(sub?-5:8),label)}${sub?text(x+w/2,y+h/2+24,sub,'f-small'):''}</g>`;
function rack(x,y,scale=1){return `<g transform="translate(${x} ${y}) scale(${scale})" class="f-rack"><rect width="64" height="132" rx="5"/>${[15,40,65,90].map(t=>`<rect x="9" y="${t}" width="46" height="16" rx="2"/><circle cx="47" cy="${t+8}" r="2"/>`).join('')}<path d="M10 118H54"/></g>`;}
function fans(x,y){return `<g transform="translate(${x} ${y})" class="f-fans"><rect x="-67" y="-39" width="134" height="78" rx="7"/>${[-34,34].map(dx=>`<g transform="translate(${dx} 0)"><circle r="25"/><path d="M0-22Q20-18 7-2Q22 2 15 20Q-1 12-4 5Q-18 16-22-2Q-8-9-2-5Z"/></g>`).join('')}</g>`;}
const wrap=(body,cls='')=>`<div class="f-stack ${cls}">${body}</div>`;
function power(role){const backup=role==='backup';return wrap(`<div class="f-photo-split"><figure>${img('finale-abilene-turbine-2026.jpg','Oracle photograph of the Abilene gas-generation plant.')}<figcaption>Abilene · Oracle · July 2026</figcaption></figure><div class="f-role"><div class="f-large-number">350 <span>MW</span></div><p>On-site gas generation</p><div class="f-role-line ${backup?'standby':''}"><b>Gas plant</b><span>${backup?'Standby':'Bridge supply'}</span><i>↓</i></div><div class="f-role-load">Data halls + cooling</div><div class="f-role-grid ${backup?'active':''}"><i>↑</i><span>${backup?'Normal supply':'Capacity expanding'}</span><b>ERCOT grid</b></div></div></div>${foot(credit(S.impact,'Crusoe · 2025 Impact Report, pp. 16, 19'),credit(S.campus,'Oracle photograph'))}`);}
function coolingDiagram(){return svg(
 rack(34,99,1.2)+text(72,294,'IT heat')+
 box(250,120,142,114,'Heat','exchange')+wire('M112 155H249','heat')+wire('M248 205H112','cool')+
 fans(713,155)+box(622,223,180,73,'Compressor')+
 wire('M393 155H543V155H644','heat')+wire('M644 197H563V205H393','cool')+
 text(490,105,'Facility water','f-small')+text(490,275,'Recirculates','f-small')+
 wire('M783 150H1018','heat')+text(962,108,'Heat to air')+text(959,199,'No evaporation','f-small')+
 wire('M712 380V298','power')+text(712,405,'Electricity')+
 text(712,76,'Air-cooled chiller'),
 'Rack heat crosses a heat exchanger into recirculating facility water. An air-cooled chiller transfers that heat, plus compressor electricity, to outdoor air. Water is not released to the atmosphere.');}
function coolingChoices(){return wrap(`<div class="f-cooling-options"><section><span class="f-option-number">01</span><h2>Direct dry cooling</h2><div class="f-option-route">Water → dry coil → air</div><p>Needs sufficiently cool air</p></section><section class="f-chosen"><span class="f-option-number">02 · ABILENE</span><h2>Air-cooled chiller</h2><div class="f-option-route">Refrigeration → outdoor air</div><p>No evaporative heat rejection</p></section><section><span class="f-option-number">03</span><h2>Water-cooled chiller</h2><div class="f-option-route">Refrigeration → wet tower</div><p>Consumes makeup water</p></section></div>${foot(credit(S.design,'Crusoe · Abilene selection'),credit(S.chiller,'Trane · chiller alternatives'))}`);}
function prefab(){return wrap(`<div class="f-build-photos"><figure>${img('finale-review-tulsa-assembly.webp','Electrical equipment being assembled in Crusoe’s manufacturing facility.')}<figcaption><strong>Factory</strong><span>Tulsa assembly floor · September 2026</span></figcaption></figure><figure>${img('finale-review-abilene-construction.jpg','Construction at the Abilene AI data center.')}<figcaption><strong>Site</strong><span>Abilene under construction</span></figcaption></figure></div><div class="f-build-join">2,500+ switchboards supplied from Tulsa to Abilene</div>${foot(credit(S.impact,'Crusoe · Abilene switchgear and prefabricated electrical skids, p. 16'),credit(S.manufacturing,'Crusoe · switchboards and factory, September 2026'),credit('https://www.oracle.com/news/resources/abilene-campus/','Oracle · Abilene construction'))}`);}
function finance(){return wrap(`<div class="f-capital"><div class="f-investors"><span class="f-date">May 2025 · announced venture</span><strong>$15 billion</strong><p>Crusoe · Blue Owl<br>Primary Digital Infrastructure</p></div><div class="f-capital-arrow"><span>Fund construction</span><b>→</b></div><div class="f-campus-icons">${svg('<path class="f-building" d="M12 180V60H178V180ZM210 180V60H376V180ZM12 60L38 35H202L178 60M210 60L237 35H397L376 60"/>'+[35,75,115,235,275,315].map(x=>`<path class="f-window" d="M${x} 90V150"/>`).join(''),'The venture funds the physical campus.','0 0 410 210')}<h2>Abilene campus</h2></div></div><div class="f-lease"><b>Long-term lease to the hyperscaler</b><span>Customer commitment supports the campus investment</span></div>${foot(credit(S.capital,'Crusoe · May 2025 venture'),credit(S.lease,'First-phase lease · October 2024'))}`);}
function expansion(){return wrap(`<div class="f-expansion"><section class="f-operating"><span class="f-date">First phase · 2025</span><h2>OpenAI workloads running</h2><div class="f-hall">${svg([0,1,2,3].map(n=>rack(25+n*88,12)).join(''),'The operating data hall remains in service.','0 0 400 160')}</div><div class="f-service-lines"><span>Power</span><span>Cooling</span><span>Network</span></div></section><div class="f-phase-boundary"><span>Connect each interface</span><b>↔</b><span>Keep the live phase operating</span></div><section class="f-building-phase"><span class="f-date">Campus expansion</span><h2>Next halls being built</h2><div class="f-hall">${svg('<path class="f-building" d="M25 145V45H360V145ZM25 45L65 12H385L360 45M90 45V145M190 45V145M290 45V145"/>','The new hall is under construction, separate from live workloads.','0 0 400 160')}</div><div class="f-service-lines"><span>Power</span><span>Cooling</span><span>Network</span></div></section></div>${foot(credit(S.live,'Crusoe · first phase running, September 2025'),credit(S.workloads,'OpenAI · early workloads, July 2025'))}`);}
function wholeMachine(){return wrap(`<div class="f-scale-story"><figure>${img('distribution-abilene-data-halls.jpg','Oracle aerial of the Abilene campus.')}<figcaption>Campus</figcaption></figure><figure>${img('finale-abilene-coolant-pipes.jpg','The actual Abilene data hall and its rack services.')}<figcaption>Data hall</figcaption></figure><figure>${img('finale-gb200-racks.png','NVIDIA GB200 NVL72 rack, manufacturer reference image.')}<figcaption>GB200 rack</figcaption></figure></div>${foot(credit(S.campus,'Oracle · Abilene campus and hall'),credit(S.workloads,'OpenAI · GB200 deployment'),credit(S.live,'Crusoe · operating campus'),credit('https://docs.nvidia.com/dgx-superpod/reference-architecture-scalable-infrastructure-gb200/latest/dgx-superpod-components.html','NVIDIA · DGX GB200 reference'))}`);}
function closing(){return `<div class="f-closing-photo"><figure>${img('finale-abilene-coolant-pipes.jpg','Inside the Abilene data hall: the physical infrastructure behind AI workloads.')}<figcaption>Abilene, Texas</figcaption></figure>${foot(credit('https://www.oracle.com/news/resources/abilene-campus/','Oracle · Abilene data hall'),credit(S.workloads,'OpenAI · workloads running'))}</div>`;}
export function integratedCasesVisual(id,state={}){switch(id){
 case 'abilene-factory':return `<div class="f-hero"><figure>${img('distribution-abilene-data-halls.jpg','Oracle aerial of the original Abilene campus on July 15, 2026.')}<figcaption>Abilene, Texas</figcaption></figure>${foot(credit(S.campus,'Oracle · July 15, 2026'))}</div>`;
 case 'abilene-workload':return wrap(`<div class="f-workload-photo">${img('finale-abilene-coolant-pipes.jpg','Inside the original Abilene data hall, from Oracle’s campus media kit.')}<div><span>OpenAI</span><strong>Training + inference</strong><span>Oracle · GB200 racks</span></div></div><div class="f-requirements"><section><b>Power</b><span>Rack distribution + backup</span></section><section><b>Heat</b><span>Cold plates + remaining air heat</span></section><section><b>Data</b><span>Connected GPU fabric</span></section></div>${foot(credit(S.workloads,'OpenAI · July 2025'),credit(S.live,'Crusoe · September 2025'),credit('https://www.oracle.com/news/resources/abilene-campus/','Oracle campus footage'))}`);
 case 'abilene-power':return power(state.powerRole||'bridge');
 case 'abilene-cooling-choice':return coolingChoices();
 case 'abilene-heat':return wrap(`<div class="f-heat-diagram">${coolingDiagram()}<div class="f-mobile-heat"><div>Rack coolant</div><b>↓ Heat exchange</b><div>Closed facility-water loop</div><b>↓</b><div>Air-cooled chiller<span>+ compressor electricity</span></div><b>↓</b><div>Heat to outdoor air</div></div></div><div class="f-tradeoff"><span>Water conserved</span><b>↔</b><span>Higher overall cost</span></div>${foot(credit(S.design,'Crusoe · published cooling design'))}`);
 case 'abilene-parallel-build':return prefab();
 case 'abilene-capital':return finance();
 case 'abilene-live-expansion':return expansion();
 case 'abilene-system':return wholeMachine();
 case 'watts-to-work':return closing();
 default:throw new Error(`Unknown integrated case scene: ${id}`);
}}
